import java.io.*;
import java.security.*;

public class DeserializationExample {
    // To fix this, we avoid standard Java serialization of untrusted data.
    // Instead, we use a safe data format like JSON with a specific schema.
    public String safeDeserializeData(String jsonInput) throws Exception {
        // Using a library like Jackson with default typing DISABLED
        // to prevent polymorphic type handling vulnerabilities.
        com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper;

        // Map the input to a specific, known Data Transfer Object (DTO)
        // This ensures only the expected fields and types are processed.
        UserDTO user = mapper.readValue(jsonInput, UserDTO.class);
        return user.getName();
    }
}

// A simple Plain Old Java Object (POJO) representing the expected data structure
class UserDTO {
    private String name;
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
}
